const msg = $input.first().json;
const chatId = msg.message?.chat?.id ?? msg.message?.from?.id ?? null;
const text = (msg.message?.text ?? '').trim();
const firstName = msg.message?.from?.first_name ?? '';
const lastName = msg.message?.from?.last_name ?? '';

return [{
  json: {
    chatId,
    text,
    firstName,
    lastName
  }
}];

// Simula obtener sesion de almacenamiento.
// REEMPLAZAR: con nodo Redis Get, MySQL, Postgres, o n8n Static Data.
// Por ahora usa $getWorkflowStaticData('global') como almacen simple.

const staticData = $getWorkflowStaticData('global');
const chatId = $json.chatId;
const text = $json.text;
const firstName = $json.firstName;
const sessionKey = 'session_' + chatId;

let session = {};
try {
  if (staticData[sessionKey]) {
    session = typeof staticData[sessionKey] === 'string'
      ? JSON.parse(staticData[sessionKey])
      : staticData[sessionKey];
  }
} catch(e) {
  session = {};
}

const state = (text === '/start' || !session.state) ? 'NEW' : session.state;

return [{
  json: {
    chatId,
    text,
    firstName,
    state,
    session
  }
}];

const chatId = $json.chatId;
const firstName = $json.firstName ?? '';

const reply = '¡Hola' + (firstName ? ' ' + firstName : '') + ' 👋!\nSoy tu asistente virtual.\n\nPara poder ayudarte, por favor envíame tu número de *cédula* o *RUC*.';

return [{
  json: {
    chatId,
    reply,
    next_state: 'AWAIT_ID',
    session: {
      state: 'AWAIT_ID',
      chatId
    }
  }
}];

const chatId = $json.chatId;
const text = $json.text;
const session = $json.session || {};

const cleaned = text.replace(/\D/g, '');

if (cleaned.length !== 10 && cleaned.length !== 13) {
  return [{
    json: {
      chatId,
      reply: '❌ El número ingresado no parece ser una *cédula* (10 dígitos) ni un *RUC* (13 dígitos).\n\nPor favor, inténtalo de nuevo:',
      next_state: 'AWAIT_ID',
      session: Object.assign({}, session, { state: 'AWAIT_ID' }),
      skipWS: true
    }
  }];
}

return [{
  json: {
    chatId,
    identificacion: cleaned,
    session: Object.assign({}, session, { identificacion: cleaned }),
    skipWS: false
  }
}];

const d = $input.first().json;
const prevData = $('Obtener y Preparar Sesion').first().json;
const chatId = prevData.chatId;
const session = prevData.session || {};

const puntos = Array.isArray(d.puntos) ? d.puntos : [];

const activos = puntos.filter(function(p) {
  return String(p && p.estado ? p.estado : '').trim().toLowerCase() === 'activo';
});

var sessionPatch = Object.assign({}, session, {
  identificacion: d.identificacion || d.documento || session.identificacion,
  nombreCliente: d.nombreCliente || null,
  contrato: d.contrato || null,
  puntosActivos: activos.map(function(p) {
    return {
      puntoId: p.puntoId,
      login: p.login,
      nombrePlan: p.nombrePlan,
      ciudad: p.ciudad,
      telefonos: p.telefonos
    };
  })
});

var next_state = '';
var selectedPuntoId = null;
var selectedLogin = null;
var reply = '';
var nombre = d.nombreCliente ? ', ' + d.nombreCliente : '';

if (activos.length === 0) {
  next_state = 'HUMAN';
  reply = 'Hola' + nombre + ' 👋\n' +
    'No encuentro un servicio *Activo* asociado a tu identificación.\n' +
    '¿Deseas que te conecte con un asesor? (Responde: *SI* / *NO*)';
} else if (activos.length === 1) {
  var p = activos[0];
  next_state = 'MAIN_MENU';
  selectedPuntoId = p.puntoId;
  selectedLogin = p.login;
  reply = 'Hola' + nombre + ' 👋\n' +
    'Tu servicio activo:\n' +
    '• ' + (p.login || '') + ' | ' + (p.nombrePlan || '') + ' (PuntoId: ' + p.puntoId + ')\n\n' +
    'Elige una opción:\n' +
    '1️⃣ Saldo / fecha de pago\n' +
    '2️⃣ Reenviar factura\n' +
    '3️⃣ Formas de pago / convenios\n' +
    '4️⃣ Plan / servicios contratados\n' +
    '5️⃣ Hablar con un asesor\n' +
    '6️⃣ Cambiar de servicio\n' +
    '0️⃣ Salir';
} else {
  next_state = 'AWAIT_PUNTO';
  var lineas = activos.map(function(p, i) {
    return (i + 1) + ') ' + (p.login || 'sin_login') + ' | ' + (p.nombrePlan || 'sin_plan') + ' | PuntoId ' + p.puntoId;
  });
  reply = 'Hola' + nombre + ' 👋\n' +
    'Tienes *' + activos.length + '* servicios activos. Elige cuál deseas consultar:\n\n' +
    lineas.join('\n');
}

sessionPatch.state = next_state;
sessionPatch.selectedPuntoId = selectedPuntoId;
sessionPatch.selectedLogin = selectedLogin;

return [{
  json: {
    chatId: chatId,
    reply: reply,
    next_state: next_state,
    selectedPuntoId: selectedPuntoId,
    selectedLogin: selectedLogin,
    session: sessionPatch
  }
}];

const chatId = $json.chatId;
const text = $json.text;
const session = $json.session || {};
const activos = Array.isArray(session.puntosActivos) ? session.puntosActivos : [];

const idx = parseInt(text, 10) - 1;

if (isNaN(idx) || idx < 0 || idx >= activos.length) {
  var lineas = activos.map(function(p, i) {
    return (i + 1) + ') ' + (p.login || 'sin_login') + ' | ' + (p.nombrePlan || 'sin_plan') + ' | PuntoId ' + p.puntoId;
  });
  return [{
    json: {
      chatId: chatId,
      reply: 'Opción inválida. Responde con un número del *1* al *' + activos.length + '*:\n\n' + lineas.join('\n'),
      next_state: 'AWAIT_PUNTO',
      session: Object.assign({}, session, { state: 'AWAIT_PUNTO' })
    }
  }];
}

var chosen = activos[idx];

return [{
  json: {
    chatId: chatId,
    reply: '✅ Servicio seleccionado:\n' +
      '• ' + (chosen.login || '') + ' | ' + (chosen.nombrePlan || '') + ' (PuntoId: ' + chosen.puntoId + ')\n\n' +
      'Elige una opción:\n' +
      '1️⃣ Saldo / fecha de pago\n' +
      '2️⃣ Reenviar factura\n' +
      '3️⃣ Formas de pago / convenios\n' +
      '4️⃣ Plan / servicios contratados\n' +
      '5️⃣ Hablar con un asesor\n' +
      '6️⃣ Cambiar de servicio\n' +
      '0️⃣ Salir',
    next_state: 'MAIN_MENU',
    selectedPuntoId: chosen.puntoId,
    selectedLogin: chosen.login,
    session: Object.assign({}, session, {
      state: 'MAIN_MENU',
      selectedPuntoId: chosen.puntoId,
      selectedLogin: chosen.login
    })
  }
}];

const chatId = $json.chatId;
const text = $json.text;
const session = $json.session || {};
const option = parseInt(text, 10);

var menuText = 'Elige una opción:\n' +
  '1️⃣ Saldo / fecha de pago\n' +
  '2️⃣ Reenviar factura\n' +
  '3️⃣ Formas de pago / convenios\n' +
  '4️⃣ Plan / servicios contratados\n' +
  '5️⃣ Hablar con un asesor\n' +
  '6️⃣ Cambiar de servicio\n' +
  '0️⃣ Salir';

if (isNaN(option) || option < 0 || option > 6) {
  return [{
    json: {
      chatId: chatId,
      reply: 'No entendí tu selección. Por favor responde con un número:\n\n' + menuText,
      next_state: 'MAIN_MENU',
      menuOption: -1,
      session: Object.assign({}, session, { state: 'MAIN_MENU' })
    }
  }];
}

var nextSt = 'MAIN_MENU';
if (option === 0) nextSt = 'EXIT';
if (option === 5) nextSt = 'HUMAN';
if (option === 6) nextSt = 'AWAIT_PUNTO';

return [{
  json: {
    chatId: chatId,
    text: text,
    menuOption: option,
    next_state: nextSt,
    session: session
  }
}];

var chatId = $json.chatId;
var session = $json.session || {};

var reply = '💳 *Información de saldo*\n\n' +
  'Servicio: ' + (session.selectedLogin || 'N/A') + '\n' +
  'PuntoId: ' + (session.selectedPuntoId || 'N/A') + '\n\n' +
  '_(Aquí se mostrará saldo, fecha máxima de pago, etc. desde tu WS)_\n\n' +
  'Elige otra opción o *0* para salir:\n' +
  '1️⃣ Saldo  2️⃣ Factura  3️⃣ Formas pago\n' +
  '4️⃣ Plan  5️⃣ Asesor  6️⃣ Cambiar  0️⃣ Salir';

return [{ json: { chatId: chatId, reply: reply, next_state: 'MAIN_MENU', session: Object.assign({}, session, { state: 'MAIN_MENU' }) } }];

var chatId = $json.chatId;
var session = $json.session || {};

var reply = '🧾 *Reenvío de factura*\n\n' +
  'Servicio: ' + (session.selectedLogin || 'N/A') + '\n\n' +
  '_(Aquí se dispara el reenvío de factura por correo o se envía PDF por Telegram)_\n\n' +
  'Elige otra opción o *0* para salir:\n' +
  '1️⃣ Saldo  2️⃣ Factura  3️⃣ Formas pago\n' +
  '4️⃣ Plan  5️⃣ Asesor  6️⃣ Cambiar  0️⃣ Salir';

return [{ json: { chatId: chatId, reply: reply, next_state: 'MAIN_MENU', session: Object.assign({}, session, { state: 'MAIN_MENU' }) } }];

var chatId = $json.chatId;
var session = $json.session || {};

var reply = '🤝 *Formas de pago y convenios*\n\n' +
  'Puedes realizar tus pagos en:\n' +
  '• Transferencia bancaria\n' +
  '• Débito automático\n' +
  '• Puntos de recaudación\n' +
  '• Pago en línea\n\n' +
  '_(Personaliza con tus canales de pago reales)_\n\n' +
  'Elige otra opción o *0* para salir:\n' +
  '1️⃣ Saldo  2️⃣ Factura  3️⃣ Formas pago\n' +
  '4️⃣ Plan  5️⃣ Asesor  6️⃣ Cambiar  0️⃣ Salir';

return [{ json: { chatId: chatId, reply: reply, next_state: 'MAIN_MENU', session: Object.assign({}, session, { state: 'MAIN_MENU' }) } }];

var chatId = $json.chatId;
var session = $json.session || {};
var activos = session.puntosActivos || [];
var selected = null;
for (var i = 0; i < activos.length; i++) {
  if (activos[i].puntoId === session.selectedPuntoId) { selected = activos[i]; break; }
}

var reply = '📦 *Plan y servicios contratados*\n\n' +
  'Servicio: ' + (session.selectedLogin || 'N/A') + '\n' +
  'Plan: ' + (selected ? selected.nombrePlan || 'N/A' : 'N/A') + '\n' +
  'Ciudad: ' + (selected ? selected.ciudad || 'N/A' : 'N/A') + '\n\n' +
  '_(Aquí puedes agregar velocidad, productos adicionales, etc.)_\n\n' +
  'Elige otra opción o *0* para salir:\n' +
  '1️⃣ Saldo  2️⃣ Factura  3️⃣ Formas pago\n' +
  '4️⃣ Plan  5️⃣ Asesor  6️⃣ Cambiar  0️⃣ Salir';

return [{ json: { chatId: chatId, reply: reply, next_state: 'MAIN_MENU', session: Object.assign({}, session, { state: 'MAIN_MENU' }) } }];

var chatId = $json.chatId;
var session = $json.session || {};

var reply = '🧑‍💻 *Conexión con asesor*\n\n' +
  'Te voy a conectar con un asesor humano. Por favor espera un momento...\n\n' +
  '_(Aquí se dispara la integración con Chatwoot, CRM, o notificación al equipo de soporte)_';

return [{ json: { chatId: chatId, reply: reply, next_state: 'HUMAN', session: Object.assign({}, session, { state: 'HUMAN' }) } }];

var chatId = $json.chatId;
var session = $json.session || {};
var activos = session.puntosActivos || [];

var reply, next_state;

if (activos.length <= 1) {
  reply = 'Solo tienes un servicio activo. No es posible cambiar.\n\n' +
    'Elige una opción:\n' +
    '1️⃣ Saldo  2️⃣ Factura  3️⃣ Formas pago\n' +
    '4️⃣ Plan  5️⃣ Asesor  0️⃣ Salir';
  next_state = 'MAIN_MENU';
} else {
  var lineas = activos.map(function(p, i) {
    return (i + 1) + ') ' + (p.login || 'sin_login') + ' | ' + (p.nombrePlan || 'sin_plan') + ' | PuntoId ' + p.puntoId;
  });
  reply = 'Tienes *' + activos.length + '* servicios activos. Elige cuál consultar:\n\n' + lineas.join('\n');
  next_state = 'AWAIT_PUNTO';
}

return [{ json: { chatId: chatId, reply: reply, next_state: next_state, session: Object.assign({}, session, { state: next_state }) } }];

var chatId = $json.chatId;

var reply = '¡Gracias por usar nuestro servicio! 👋\nSi necesitas algo más, envía /start para comenzar de nuevo.';

return [{ json: { chatId: chatId, reply: reply, next_state: 'EXIT', session: { state: 'NEW', chatId: chatId } } }];

var chatId = $json.chatId;
var text = ($json.text || '').trim().toUpperCase();
var session = $json.session || {};

if (text === 'NO' || text === '/START') {
  return [{ json: { chatId: chatId, reply: 'Entendido. Si necesitas algo más, envía /start.', next_state: 'NEW', session: { state: 'NEW', chatId: chatId } } }];
}

if (text === 'SI' || text === 'SÍ') {
  return [{ json: { chatId: chatId, reply: '🧑‍💻 Te estamos conectando con un asesor. Por favor espera...', next_state: 'HUMAN', session: Object.assign({}, session, { state: 'HUMAN' }) } }];
}

return [{ json: { chatId: chatId, reply: 'Un asesor te atenderá pronto. Si deseas reiniciar, envía /start.', next_state: 'HUMAN', session: Object.assign({}, session, { state: 'HUMAN' }) } }];

// Guardar sesion en Static Data del workflow
// REEMPLAZAR con Redis/DB si prefieres persistencia externa
var staticData = $getWorkflowStaticData('global');
var chatId = $json.chatId;
var session = $json.session || {};
var sessionKey = 'session_' + chatId;

staticData[sessionKey] = JSON.stringify(session);

return [{ json: { success: true, chatId: chatId, state: session.state } }];
